# Deploy this exported SLM fine-tune to a SageMaker real-time endpoint in YOUR
# OWN AWS account. Generated by the SLM platform — values in manifest.json.
#
# Usage:
#   ./deploy.sh --profile <aws_profile> --region <region> [--bucket <s3_bucket>] [--name <endpoint>]
#
#   --profile  AWS CLI profile to deploy with (your account, not the platform's)
#   --region   AWS region for the endpoint (e.g. us-east-1)
#   --bucket   S3 bucket in YOUR account to stage the model (default: auto-named)
#   --name     Endpoint name (default: deterministic from the model id). Pass a
#              fixed name so RE-RUNS reuse the same endpoint instead of orphaning one.
#
# RE-RUNNABLE / IDEMPOTENT: every step checks before it acts. If a prior run got
# partway (image pushed, model uploaded, role created, endpoint half-made) and
# failed, just run the SAME command again — it skips finished work and resumes:
#   • ECR image with this tag already present  → skip build + push
#   • model.tar.gz already staged in S3         → skip repackage + upload
#   • exec role already exists                  → reuse
#   • SageMaker model / endpoint-config exist   → reuse
#   • endpoint exists                           → update it to the new config
#
# What it does:
#   1. build the inference image FROM hiyouga/llamafactory:<baseImageTag> (the
#      SAME image the model trained on — exact versions) and push to YOUR ECR
#   2. download the fine-tuned weights, repackage into a SageMaker model.tar.gz,
#      upload to your S3
#   3. create/reuse Model -> EndpointConfig -> Endpoint and wait for it
#   4. print a test snippet
#
# Requires: docker (to build the image) + the AWS CLI. The LLaMA-Factory base
# image is public on Docker Hub; this script pulls it during the build.
set -euo pipefail

PROFILE="" REGION="" BUCKET="" NAME=""
while [ $# -gt 0 ]; do
  case "$1" in
    --profile) PROFILE="$2"; shift 2 ;;
    --region)  REGION="$2";  shift 2 ;;
    --bucket)  BUCKET="$2";  shift 2 ;;
    --name)    NAME="$2";    shift 2 ;;
    *) echo "unknown arg: $1" >&2; exit 2 ;;
  esac
done
[ -n "$PROFILE" ] && [ -n "$REGION" ] || { echo "ERROR: --profile and --region are required" >&2; exit 2; }

HERE="$(cd "$(dirname "$0")" && pwd)"
cd "$HERE"
AWSP=(--profile "$PROFILE" --region "$REGION")

# --- read the manifest (jq if present, else python) ------------------------
read_manifest() {
  if command -v jq >/dev/null 2>&1; then jq -r ".$1 // empty" manifest.json
  else python3 -c "import json,sys; print(json.load(open('manifest.json')).get('$1','') or '')"; fi
}
MODEL_ID="$(read_manifest modelId)"
ENGINE="$(read_manifest engine)"                 # llama_factory | sagemaker_serverless
[ -n "$ENGINE" ] && [ "$ENGINE" != "None" ] || ENGINE="llama_factory"
DEPLOY_MODE="$(read_manifest deployMode)"        # merged | adapter
WEIGHTS_SUBDIR="$(read_manifest weightsSubdir)"  # merged | adapter
BASE_MODEL="$(read_manifest hfBaseModel)"
WEIGHTS_URL="$(read_manifest weightsUrl)"        # llama_factory: one tarball URL
WEIGHTS_S3_URI="$(read_manifest artifactS3Uri)"  # s3://… source (tarball OR prefix)
INSTANCE="$(read_manifest suggestedInstance)"
[ -n "$INSTANCE" ] || INSTANCE="ml.g5.2xlarge"
TRUST_REMOTE_CODE="$(read_manifest trustRemoteCode)"  # "True" when the base ships
                                                 # its architecture as repo-side
                                                 # modeling code (config auto_map)
LF_TAG="$(read_manifest baseImageTag)"           # LLaMA-Factory tag the model trained on
[ -n "$LF_TAG" ] && [ "$LF_TAG" != "None" ] || LF_TAG="0.9.4"

ACCOUNT="$(aws sts get-caller-identity "${AWSP[@]}" --query Account --output text)"
[ -n "$BUCKET" ] || BUCKET="slm-export-${ACCOUNT}-${REGION}"
# Deterministic endpoint name (no timestamp) so RE-RUNS target the same endpoint.
# Override with --name. Sanitized to SageMaker's [a-zA-Z0-9-], <=63 chars.
[ -n "$NAME" ] || NAME="slm-${MODEL_ID}"
ENDPOINT="$(echo "$NAME" | tr -c 'a-zA-Z0-9-' '-' | cut -c1-63 | sed 's/-*$//')"

echo "→ account=$ACCOUNT region=$REGION mode=$DEPLOY_MODE instance=$INSTANCE"
echo "→ endpoint=$ENDPOINT  bucket=$BUCKET  lf_tag=$LF_TAG"

# --- 1. build + push the inference image (SKIP if the tag already exists) ----
# Same image the model trained on → exact transformers/torch/vllm, no mismatch.
ECR_REPO="slm-inference"
IMAGE_TAG="${MODEL_ID}-lf${LF_TAG}"
IMAGE_URI="${ACCOUNT}.dkr.ecr.${REGION}.amazonaws.com/${ECR_REPO}:${IMAGE_TAG}"
aws ecr describe-repositories --repository-names "$ECR_REPO" "${AWSP[@]}" >/dev/null 2>&1 \
  || aws ecr create-repository --repository-name "$ECR_REPO" "${AWSP[@]}" >/dev/null
if aws ecr describe-images --repository-name "$ECR_REPO" --image-ids imageTag="$IMAGE_TAG" "${AWSP[@]}" >/dev/null 2>&1; then
  echo "→ image $IMAGE_TAG already in ECR — skipping build + push"
else
  echo "→ building inference image FROM hiyouga/llamafactory:${LF_TAG} (one-time) …"
  aws ecr get-login-password "${AWSP[@]}" \
    | docker login --username AWS --password-stdin "${ACCOUNT}.dkr.ecr.${REGION}.amazonaws.com"
  docker build --build-arg "LF_TAG=${LF_TAG}" -t "$IMAGE_URI" "$HERE"
  docker push "$IMAGE_URI"
fi

# --- 2. stage the model.tar.gz in S3 (SKIP if already uploaded) -------------
MODEL_S3="s3://$BUCKET/slm-exports/$ENDPOINT/model.tar.gz"
aws s3api head-bucket --bucket "$BUCKET" "${AWSP[@]}" 2>/dev/null || {
  echo "→ creating bucket $BUCKET"
  if [ "$REGION" = "us-east-1" ]; then
    aws s3api create-bucket --bucket "$BUCKET" "${AWSP[@]}" >/dev/null
  else
    aws s3api create-bucket --bucket "$BUCKET" "${AWSP[@]}" \
      --create-bucket-configuration LocationConstraint="$REGION" >/dev/null
  fi
}
if aws s3api head-object --bucket "$BUCKET" --key "slm-exports/$ENDPOINT/model.tar.gz" "${AWSP[@]}" >/dev/null 2>&1; then
  echo "→ model.tar.gz already staged at $MODEL_S3 — skipping download + repackage"
else
  WORK="$(mktemp -d)"; trap 'rm -rf "$WORK"' EXIT
  PKG="$WORK/pkg"; mkdir -p "$PKG"
  if [ "$ENGINE" = "sagemaker_serverless" ]; then
    # Serverless output is an UNCOMPRESSED prefix of loose files already in the
    # right HF layout (merged model, or LoRA adapter for gated) — no tarball to
    # extract, no subdir to pick. Try a fast recursive S3 copy of the prefix; if
    # there's no direct access, fall back to the per-file presigned URLs.
    echo "→ downloading serverless weights (loose files) …"
    DL_OK=0
    if [ -n "$WEIGHTS_S3_URI" ] && [ "$WEIGHTS_S3_URI" != "None" ]; then
      SRC_REGION="$(read_manifest artifactRegion)"; [ -n "$SRC_REGION" ] || SRC_REGION="us-east-1"
      echo "  trying fast recursive copy from $WEIGHTS_S3_URI …"
      if aws s3 cp "${WEIGHTS_S3_URI%/}/" "$PKG/" --recursive --profile "$PROFILE" --region "$SRC_REGION" 2>/dev/null; then
        DL_OK=1; echo "  ✓ recursive copy done"
      else
        echo "  (no direct S3 access — falling back to per-file presigned links)"
      fi
    fi
    if [ "$DL_OK" = "0" ]; then
      echo "  downloading via per-file presigned URLs …"
      # manifest.weightsFiles = [{name,url,size}, …]. Recreate each file (incl.
      # any nested path) under $PKG via its presigned URL.
      python3 - "$PKG" <<'PYEOF'
import json, os, sys, urllib.request
pkg = sys.argv[1]
files = json.load(open("manifest.json")).get("weightsFiles", [])
if not files:
    sys.exit("manifest has no weightsFiles — re-export from the platform")
for f in files:
    dest = os.path.join(pkg, f["name"])
    os.makedirs(os.path.dirname(dest) or pkg, exist_ok=True)
    print(f"    {f['name']} ({f.get('size',0)} bytes)")
    urllib.request.urlretrieve(f["url"], dest)
PYEOF
    fi
  else
    # LLaMA-Factory: a single model.tar.gz holding adapter/ + merged/.
    echo "→ downloading weights …"
    DL_OK=0
    if [ -n "$WEIGHTS_S3_URI" ] && [ "$WEIGHTS_S3_URI" != "None" ]; then
      SRC_REGION="$(read_manifest artifactRegion)"; [ -n "$SRC_REGION" ] || SRC_REGION="us-east-1"
      echo "  trying fast parallel copy from $WEIGHTS_S3_URI …"
      if aws s3 cp "$WEIGHTS_S3_URI" "$WORK/model.tar.gz" --profile "$PROFILE" --region "$SRC_REGION" 2>/dev/null; then
        DL_OK=1; echo "  ✓ parallel copy done"
      else
        echo "  (no direct S3 access — falling back to the presigned link)"
      fi
    fi
    if [ "$DL_OK" = "0" ]; then
      echo "  downloading via presigned URL …"
      curl -fSL "$WEIGHTS_URL" -o "$WORK/model.tar.gz"
    fi
    mkdir -p "$WORK/extract" && tar -xzf "$WORK/model.tar.gz" -C "$WORK/extract"
    # The platform tarball contains adapter/ and merged/. Pick the licensed one.
    SRC="$WORK/extract/$WEIGHTS_SUBDIR"; [ -d "$SRC" ] || SRC="$WORK/extract"
    cp -r "$SRC"/. "$PKG/"
  fi
  # inference.py is in the IMAGE, so the model tarball is just the weights.
  tar -czf "$WORK/sagemaker-model.tar.gz" -C "$PKG" .
  aws s3 cp "$WORK/sagemaker-model.tar.gz" "$MODEL_S3" "${AWSP[@]}"
fi

# --- 3. execution role (reuse if it exists) ---------------------------------
ROLE_NAME="slm-export-sagemaker-exec"
ROLE_ARN="$(aws iam get-role --role-name "$ROLE_NAME" --profile "$PROFILE" --query 'Role.Arn' --output text 2>/dev/null || true)"
if [ -z "$ROLE_ARN" ] || [ "$ROLE_ARN" = "None" ]; then
  echo "→ creating execution role $ROLE_NAME"
  TRUST='{"Version":"2012-10-17","Statement":[{"Effect":"Allow","Principal":{"Service":"sagemaker.amazonaws.com"},"Action":"sts:AssumeRole"}]}'
  ROLE_ARN="$(aws iam create-role --role-name "$ROLE_NAME" --profile "$PROFILE" \
    --assume-role-policy-document "$TRUST" --query 'Role.Arn' --output text)"
  for P in AmazonSageMakerFullAccess AmazonS3FullAccess AmazonEC2ContainerRegistryReadOnly; do
    aws iam attach-role-policy --role-name "$ROLE_NAME" --profile "$PROFILE" \
      --policy-arn "arn:aws:iam::aws:policy/$P"
  done
  echo "→ waiting for role to propagate…"; sleep 15
else
  echo "→ reusing execution role $ROLE_ARN"
fi

# Container env (adapter mode pulls the gated base from HF → needs a token).
CONTAINER="Image=$IMAGE_URI,ModelDataUrl=$MODEL_S3"
# Container env, assembled for BOTH delivery modes. Adapter mode needs the base
# model id (plus a token for gated bases); either mode may need repo-side modeling
# code enabled. Env vars go INSIDE --primary-container as Environment={...} (NOT a
# separate flag).
ENV_PAIRS=""
if [ "$DEPLOY_MODE" = "adapter" ]; then
  [ -n "${HF_TOKEN:-}" ] || echo "⚠️  adapter mode: export HF_TOKEN first (gated base $BASE_MODEL) or the base download will 403"
  ENV_PAIRS="SLM_BASE_MODEL=$BASE_MODEL,HF_TOKEN=${HF_TOKEN:-}"
fi
# inference.py defaults this OFF, so it must be passed explicitly for the models
# that cannot load without it (MiniCPM, GLM, InternLM, Phi, LFM2). Python's json
# writes the bool as True/False; accept either casing.
case "$TRUST_REMOTE_CODE" in
  true|True|TRUE|1)
    if [ -n "$ENV_PAIRS" ]; then ENV_PAIRS="$ENV_PAIRS,"; fi
    ENV_PAIRS="${ENV_PAIRS}SLM_TRUST_REMOTE_CODE=true"
    ;;
esac
if [ -n "$ENV_PAIRS" ]; then
  CONTAINER="$CONTAINER,Environment={$ENV_PAIRS}"
fi

# --- 4. Model -> EndpointConfig -> Endpoint (create or reuse) ---------------
# Version model + config names so a re-run with NEW weights/image makes a fresh
# pair and updates the endpoint to it (SageMaker model/config are immutable).
SUFFIX="$(echo "$IMAGE_TAG" | tr -c 'a-zA-Z0-9-' '-' | cut -c1-30)"
MODEL_NAME="$(echo "${ENDPOINT}-${SUFFIX}" | cut -c1-63 | sed 's/-*$//')"
CFG_NAME="$MODEL_NAME"
SM=(aws sagemaker "${AWSP[@]}")

if "${SM[@]}" describe-model --model-name "$MODEL_NAME" >/dev/null 2>&1; then
  echo "→ model $MODEL_NAME exists — reuse"
else
  echo "→ creating model $MODEL_NAME"
  "${SM[@]}" create-model --model-name "$MODEL_NAME" --execution-role-arn "$ROLE_ARN" \
    --primary-container "$CONTAINER" >/dev/null
fi
if "${SM[@]}" describe-endpoint-config --endpoint-config-name "$CFG_NAME" >/dev/null 2>&1; then
  echo "→ endpoint-config $CFG_NAME exists — reuse"
else
  echo "→ creating endpoint-config $CFG_NAME"
  "${SM[@]}" create-endpoint-config --endpoint-config-name "$CFG_NAME" \
    --production-variants "VariantName=AllTraffic,ModelName=$MODEL_NAME,InstanceType=$INSTANCE,InitialInstanceCount=1" >/dev/null
fi

EP_STATUS="$("${SM[@]}" describe-endpoint --endpoint-name "$ENDPOINT" --query EndpointStatus --output text 2>/dev/null || true)"
if [ -z "$EP_STATUS" ]; then
  echo "→ creating endpoint $ENDPOINT (takes ~5–10 min)"
  "${SM[@]}" create-endpoint --endpoint-name "$ENDPOINT" --endpoint-config-name "$CFG_NAME" >/dev/null
elif [ "$EP_STATUS" = "InService" ] || [ "$EP_STATUS" = "Failed" ]; then
  echo "→ endpoint $ENDPOINT exists ($EP_STATUS) — updating to the latest config"
  "${SM[@]}" update-endpoint --endpoint-name "$ENDPOINT" --endpoint-config-name "$CFG_NAME" >/dev/null
else
  echo "→ endpoint $ENDPOINT is $EP_STATUS — waiting for it to settle"
fi
echo "→ waiting for endpoint to be in service …"
"${SM[@]}" wait endpoint-in-service --endpoint-name "$ENDPOINT"

echo ""
echo "✅ Endpoint in service: $ENDPOINT"
echo ""
echo "Test it:"
echo "  aws sagemaker-runtime invoke-endpoint --profile $PROFILE --region $REGION \\"
echo "    --endpoint-name $ENDPOINT --content-type application/json \\"
echo "    --body '{\"prompt\":\"Tell me a joke\",\"max_new_tokens\":64}' /dev/stdout"
echo ""
echo "Delete when done (stops billing):"
echo "  aws sagemaker delete-endpoint --profile $PROFILE --region $REGION --endpoint-name $ENDPOINT"
